# Feature Implementation: User Authentication

## Authentication Flow

1. User opens the app and is redirected to the login screen.
2. User enters their email and password.
3. The app validates the credentials and redirects the user to the protected dashboard.

### Code

```typescript
// src/pages/auth.tsx
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { LoadingSpinner } from '../components/LoadingSpinner';

interface AuthFormProps {
  onSubmit: (email: string, password: string) => Promise<void>;
  isLoading: boolean;
}

const AuthForm: React.FC<AuthFormProps> = ({ onSubmit, isLoading }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const { login, isLoading: authLoading } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const result = await login(email, password);
    if (result.success) {
      navigate('/dashboard');
    } else {
      setError(result.message || 'Invalid email or password.');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="form-group">
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          disabled={authLoading}
        />
      </div>

      <div className="form-group">
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          disabled={authLoading}
        />
      </div>

      <button type="submit" disabled={authLoading}>
        {authLoading ? (
          <LoadingSpinner />
        ) : (
          'Login'
        )}
      </button>

      {error && <p className="error">{error}</p>}
    </form>
  );
};

export default AuthForm;
```

## Next Steps

1. Add the login endpoint to the backend.
2. Create the protected routes.
3. Implement the password reset feature.
4. Add error handling and loading states.

